# BOSS PORTRAITS END


def boss_icon_tiles():
    """The two portraits, 48 tiles each in reading order (6 by 8)."""
    tiles = []
    for p in range(2):
        px = BOSS_PORTRAITS[p * 48 * 64 * 2:(p + 1) * 48 * 64 * 2]
        for i in range(48):
            r, c = divmod(i, 6)
            tiles.append(b''.join(
                px[((r * 8 + y) * 48 + c * 8) * 2:
                   ((r * 8 + y) * 48 + c * 8 + 8) * 2] for y in range(8)))
    return tiles


